    df_jadual["TARIKH_CLEAN"] = df_jadual["TARIKH"].astype(str).str.extract(r"(\d{4}-\d{2}-\d{2})")
    df_jadual["MP_CLEAN"] = df_jadual["MATA PELAJARAN"].astype(str).str.replace("\n", " ").str.strip()
